import random
import math
from fractions import Fraction

def gaussian_elimination(matrix):
    n = len(matrix)
    for i in range(n):
        # Find pivot in column i
        max_row = i
        for j in range(i+1, n):
            if abs(matrix[j][i]) > abs(matrix[max_row][i]):
                max_row = j

        # Swap rows
        matrix[i], matrix[max_row] = matrix[max_row], matrix[i]

        # Eliminate entries below pivot
        pivot = matrix[i][i]
        for j in range(i+1, n):
            factor = Fraction(matrix[j][i], pivot)
            for k in range(n):
                matrix[j][k] -= factor * matrix[i][k]

    rank = 0
    for row in matrix:
        if any(row):
            rank += 1
    return rank

def random_cnf(n, m):
    clauses = []
    variables = list(range(1, n+1))
    for _ in range(m):
        clause = []
        for _ in range(random.randint(1, n)):
            var = random.choice(variables)
            if random.choice([True, False]):
                clause.append(var)
            else:
                clause.append(-var)
        clauses.append(clause)
    return clauses

def incidence_matrix(cnf):
    n = len(cnf)
    m = max(len(clause) for clause in cnf)
    matrix = [[0] * (n + m) for _ in range(n)]

    var_index = {i: j for j, i in enumerate(range(1, n+1))}
    neg_var_index = {-i: j for j, i in enumerate(range(1, n+1))}

    for i, clause in enumerate(cnf):
        for lit in clause:
            if lit > 0:
                matrix[i][var_index[lit]] = 1
            else:
                matrix[i][neg_var_index[-lit]] = 1

    return matrix

def run_trial(seed: int) -> dict:
