        results.append(rank_value)

    mean_rank = sum(results) / len(results)
    conjecture_holds = all(abs(r - (n**2 / math.log(n))) <= 10 for n, r in zip(n_values, results))
    counterexample = "" if conjecture_holds else "mapping_undefined"

